// Step 1: Define FAQs with keyword matching
const faqs = [
  {
    keywords: ["working hours", "open", "hours", "timing"],
    answer: "We are open Monday to Friday, 9 AM to 6 PM Eastern Time."
  },
  {
    keywords: ["location", "address", "where are you"],
    answer: "We are located in New York City, but we serve clients nationwide."
  },
  {
    keywords: ["pricing", "cost", "price", "charges"],
    answer: "Our basic package starts at $99 per month. Contact us for custom pricing."
  },
  {
    keywords: ["contact", "email", "phone", "support"],
    answer: "You can email us at help@company.com or call 1-800-555-0123."
  }
];

// Step 2: Extract input from webhook
const input = $input.all()[0].json;

// Step 3: Normalize query for matching
function normalize(text) {
  return String(text || "").toLowerCase().replace(/[^\w\s]/g, "").trim();
}

const rawQuestion = input.body?.query || input.query || input.message?.content || input.transcript || "";
const normalizedQuestion = normalize(rawQuestion);
const toolCallId = String(input.body?.toolCallId || input.toolCallId || "1");

console.log("Normalized question:", normalizedQuestion);
console.log("ToolCallId:", toolCallId);

// Step 4: Find the matching answer
let matchedAnswer = null;

for (const faq of faqs) {
  for (const keyword of faq.keywords) {
    if (normalizedQuestion.includes(normalize(keyword))) {
      matchedAnswer = faq.answer;
      break;
    }
  }
  if (matchedAnswer) break;
}

// Step 5: Prepare and return response
const answer = matchedAnswer || "I don't have that information right now. Please contact our support team at help@company.com for assistance.";

return {
  json: {
    results: [
      {
        toolCallId,
        result: answer
      }
    ]
  }
};
